implementation:
#include <linux/skbuff.h>
#include <linux/ip.h>
#include <linux/ipv6.h>
#include <linux/udp.h>
#include <linux/errno.h>

struct sk_buff *fragment_udp_packet_ipv6(struct sk_buff *skb, u32 features) {
    if (!skb || skb->len <= 0) {
        return ERR_PTR(-EINVAL);
    }

    if (!skb_is_gso(skb)) {
        return ERR_PTR(-EINVAL);
    }

    if (skb->len <= skb->dev->mtu) {
        return skb;
    }

    if ((features & NETIF_F_IPV6_CSUM) == 0) {
        return ERR_PTR(-EOPNOTSUPP);
    }

    skb = skb_share_check(skb, GFP_ATOMIC);
    if (IS_ERR(skb)) {
        return skb;
    }

    skb_set_transport_header(skb, skb_transport_offset(skb));

    struct udphdr *udph = udp_hdr(skb);
    if (!udph) {
        return ERR_PTR(-EINVAL);
    }

    udph->check = 0;
    udph->check = csum_tcpudp_magic(ipv6_hdr(skb)->saddr, ipv6_hdr(skb)->daddr, skb->len, IPPROTO_UDP, skb_checksum(skb, 0, skb->len, 0));

    skb = skb_gso_segment(skb, features);
    if (IS_ERR(skb)) {
        return skb;
    }

    return skb;
}
